"use strict";
const http = require("node:http");
http.createServer((req, res) => {
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  if (req.url === "/api/sante") { res.writeHead(200); return res.end(JSON.stringify({ statut: "ok" })); }
  if (req.url === "/api/livres") { res.writeHead(200); return res.end(JSON.stringify({ donnees: [{ id: 1, titre: "Web" }] })); }
  res.writeHead(404); res.end(JSON.stringify({ erreur: "introuvable" }));
}).listen(3000, () => console.log("http://localhost:3000/api/sante"));
